import dorglq = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const WORK = new Float64Array( 10 );
	dorglq( 'column-major', 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const A = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const WORK = new Float64Array( 10 );
	dorglq( 5, 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( true, 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( false, 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( null, 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( void 0, 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( [], 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( {}, 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( ( x: number ): number => x, 2, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const A = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const WORK = new Float64Array( 10 );
	dorglq( 'column-major', '5', 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( 'column-major', true, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( 'column-major', false, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( 'column-major', null, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( 'column-major', void 0, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( 'column-major', [], 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( 'column-major', {}, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
	dorglq( 'column-major', ( x: number ): number => x, 3, 2, A, 2, TAU, WORK, 10 ); // $ExpectError
}

