// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const WORK = new Float64Array( 10 );
	dorglq(); // $ExpectError
	dorglq( 'column-major' ); // $ExpectError
	dorglq( 'column-major', 2 ); // $ExpectError
	dorglq( 'column-major', 2, 3 ); // $ExpectError
	dorglq( 'column-major', 2, 3, 2 ); // $ExpectError
	dorglq( 'column-major', 2, 3, 2, A ); // $ExpectError
	dorglq( 'column-major', 2, 3, 2, A, 2 ); // $ExpectError
	dorglq( 'column-major', 2, 3, 2, A, 2, TAU ); // $ExpectError
	dorglq( 'column-major', 2, 3, 2, A, 2, TAU, WORK ); // $ExpectError
	dorglq( 'column-major', 2, 3, 2, A, 2, TAU, WORK, 10, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const WORK = new Float64Array( 10 );
	dorglq.ndarray( 2, 3, 2, A, 1, 2, 0, TAU, 1, 0, WORK, 1, 0, 10 ); // $ExpectType number
}

